# ---------------------------------------------------------------- rendering
def _missions(t, lang, first_day, items):
    out = []
    for i, (k, m, mins, title, desc, done) in enumerate(items):
        d = first_day + i
        out.append(f'<li><span class="gp-d" aria-hidden="true"><b>{d:02d}</b><small>{t(WD[(d - 1) % 7])}</small></span><div>'
                   f'<h3><span class="sr">{t(DAY)} {d} · </span>{t(title)}</h3><p class="gp-meta">{t(KIND[k])} · {t(MKT[m])} · {mins} min</p>'
                   f'<p>{t(desc)}</p><p class="gp-done"><b>{t(DONE)}</b> {t(done)}</p></div></li>')
    return '<ol class="gp-missions">' + "".join(out) + "</ol>"

def _weeks(t, lang, first_day, weeks):
    html_, d = "", first_day
    for title, lead, items in weeks:
        html_ += f'<h2>{t(title)}</h2><p>{t(lead)}</p>' + _missions(t, lang, d, items)
        d += len(items)
    return html_

_ul = lambda t, xs: "<ul>" + "".join(f"<li>{t(x)}</li>" for x in xs) + "</ul>"
_ol = lambda t, xs: "<ol>" + "".join(f"<li>{t(x)}</li>" for x in xs) + "</ol>"
_tbl = lambda t, rows: '<table class="tbl"><tbody>' + "".join(f"<tr><th>{t(a)}</th><td>{t(b)}</td></tr>" for a, b in rows) + "</tbody></table>"
_checks = lambda t, xs: '<ul class="gp-checks">' + "".join(f"<li>{t(x)}</li>" for x in xs) + "</ul>"
_note = lambda t, k, x: f'<aside class="gp-note"><b>{t(k)}</b><p>{t(x)}</p></aside>'

def _month_nav(lang, t, cur):
    """The three months, with the one being read marked."""
    items = "".join(f'<a href="{href(lang, GP_MONTHS[i])}"{" aria-current=\"page\"" if i == cur else ""}><small>{t(MONTH(i + 1))}<span class="gp-span"> · {t(SPANS[i])}</span></small><b>{t(NAMES[i])}</b></a>' for i in range(3))
    return f'<nav class="gp-nav" aria-label="{t(T("The 90-day gameplan","Le plan de 90 jours","El plan de 90 días"))}">{items}</nav>'

def _month_page(lang, t, n, kick, h1, lead, body, title, desc, cta_track):
    import ui
    hero = ui.hero(t, kick, h1, lead, cta=ui.btn(t(CREATE_FREE), SIGNUP, lg=True, attrs=f'data-track="{cta_track}"'))
    nxt = [GP_MONTHS[n]] if n < 3 else []
    b = (ui.sec(_month_nav(lang, t, n - 1), "t", "months")
         + ui.sec(ui.doc(t, localize(lang, body)) + f'<p class="fine" style="margin-top:40px">{t(DISCLAIM)}</p>', "n", "plan")
         + ui.read_next(lang, t, (nxt + [GP_HUB, "trading-templates.html", "prop-firms/index.html"])[:3])
         + ui.final(lang, t))
    ld = jsonld({"@context": "https://schema.org", "@type": "Article", "headline": t(title).split(" · ")[0], "description": t(desc), "inLanguage": lang, "datePublished": "2026-10-19",
                 "isPartOf": {"@type": "CreativeWork", "name": t(T("The 90-day prop firm gameplan","Le plan prop firm de 90 jours","El plan prop firm de 90 días")), "url": f"https://{DOMAIN}{href(lang, GP_HUB)}"},
                 "publisher": {"@id": f"https://{DOMAIN}/#org"}, "author": {"@type": "Organization", "name": "Sweep"}})
    return (t(title), t(desc), hero + b, ld)

def page_gp_month1(lang, t):
    H = lambda x: f"<h2>{t(x)}</h2>"
    body = (H(T("How Month 1 works","Comment marche le mois 1","Cómo funciona el mes 1")) + _ul(t, M1_HOW)
            + H(T("Pick your track","Choisis ton parcours","Elige tu recorrido")) + _tbl(t, TRACKS)
            + H(T("Your guardrails","Tes garde-fous","Tus barreras")) + f'<p>{t(T("Set them on Day 1. They don’t move for 30 days.","Fixe-les au jour 1. Ils ne bougent pas pendant 30 jours.","Fíjalas el día 1. No se mueven durante 30 días."))}</p>' + _ol(t, RULES_1_8)
            + f'<p>{t(T("Write down your numbers: your market (MES or MNQ), your trading window, your max risk per trade and your daily stop in dollars, and your firm and account type.","Écris tes chiffres : ton marché (MES ou MNQ), ta fenêtre de trading, ton risque max par trade et ton stop du jour en dollars, ta firme et ton type de compte.","Escribe tus cifras: tu mercado (MES o MNQ), tu ventana de trading, tu riesgo máximo por operación y tu stop diario en dólares, tu firma y tu tipo de cuenta."))}</p>'
            + _note(t, T("How to set them","Comment les fixer","Cómo fijarlas"), T("Your daily stop (2R plus slippage) should stay well below your firm’s daily loss limit and far from your drawdown. Your displayed balance is not your risk budget. A stop doesn’t guarantee your exit price. The <a href=\"@position-size-calculator.html\">position size calculator</a> does the math for you.","Ton stop du jour (2R plus le glissement) doit rester bien sous la limite de perte quotidienne de ta firme et loin de ton drawdown. Le solde affiché n’est pas ton budget de risque. Un stop ne garantit pas ton prix de sortie. Le <a href=\"@position-size-calculator.html\">calculateur de taille de position</a> fait le calcul pour toi.","Tu stop diario (2R más el deslizamiento) debe quedar muy por debajo del límite de pérdida diaria de tu firma y lejos de tu drawdown. El saldo que ves no es tu presupuesto de riesgo. Un stop no garantiza tu precio de salida. La <a href=\"@position-size-calculator.html\">calculadora de tamaño de posición</a> hace el cálculo por ti."))
            + H(T("The Sweep Setup","Le Sweep Setup","El Sweep Setup")) + f'<p>{t(T("One simple setup, so you can focus on execution. Price sweeps an obvious level, then takes it back.","Un setup simple, pour te concentrer sur l’exécution. Le prix balaie un niveau évident, puis le reprend.","Un setup sencillo, para que te concentres en la ejecución. El precio barre un nivel evidente y luego lo recupera."))}</p>' + _tbl(t, SETUP)
            + _note(t, T("Be clear about what this is","Sois clair sur ce que c’est","Ten claro lo que es"), T("A learning setup to practice execution, not a proven edge. Your Month 1 goal is to execute it exactly as written, profitable or not. Edge comes later, from your own data.","Un setup d’apprentissage pour pratiquer l’exécution, pas un edge prouvé. Ton but au mois 1 est de l’exécuter exactement comme écrit, rentable ou non. L’edge viendra plus tard, de tes propres données.","Un setup de aprendizaje para practicar la ejecución, no una ventaja probada. Tu meta en el mes 1 es ejecutarlo exactamente como está escrito, rentable o no. La ventaja llegará después, de tus propios datos."))
            + f'<h3>{t(T("Cheat sheet","Aide-mémoire","Chuleta"))}</h3>' + _tbl(t, SPECS)
            + f'<p class="fine">{t(T("Micros are 1/10 of ES and NQ. Example: a 10-point stop on MNQ = 10 × $2 = $20 of risk, before fees and slippage. Check current specs on <a href=\"@futures-contracts.html\">our contract specs</a> or at cmegroup.com.","Les micros valent 1/10 de l’ES et du NQ. Exemple : un stop de 10 points sur le MNQ = 10 × 2 $ = 20 $ de risque, avant frais et glissement. Vérifie les spécifications à jour sur <a href=\"@futures-contracts.html\">nos fiches contrats</a> ou sur cmegroup.com.","Los micros valen 1/10 del ES y del NQ. Ejemplo: un stop de 10 puntos en el MNQ = 10 × 2 $ = 20 $ de riesgo, antes de comisiones y deslizamiento. Revisa las especificaciones actuales en <a href=\"@futures-contracts.html\">nuestras fichas de contratos</a> o en cmegroup.com."))}</p>'
            + H(T("Your session routine","Ta routine de séance","Tu rutina de sesión")) + f'<p>{t(T("The same routine every market day, until it’s automatic.","La même routine chaque jour de marché, jusqu’à ce qu’elle soit automatique.","La misma rutina cada día de mercado, hasta que sea automática."))}</p>'
            + "".join(f"<h3>{t(h)}</h3>" + _checks(t, xs) for h, xs in ROUTINE)
            + f'<h3>{t(T("Prop firm vocabulary","Le vocabulaire des prop firms","El vocabulario de las prop firms"))}</h3>' + _tbl(t, VOCAB)
            + _weeks(t, lang, 1, M1_WEEKS)
            + H(T("Your session journal","Ton journal de séance","Tu diario de sesión")) + f'<p>{t(T("After every session, no-trade days included, write down:","Après chaque séance, journées sans trade comprises, note :","Después de cada sesión, días sin operaciones incluidos, anota:"))}</p>' + _ul(t, M1_JOURNAL)
            + f'<p>{t(T("The process score rates how well you followed your plan, not your P&L. A red day executed perfectly is a 5. Prefer paper? Print the <a href=\"@trading-templates.html\">free daily journal template</a>.","La note de processus mesure à quel point tu as suivi ton plan, pas ton P&L. Une journée rouge exécutée parfaitement vaut 5. Tu préfères le papier ? Imprime le <a href=\"@trading-templates.html\">modèle gratuit de journal quotidien</a>.","La nota de proceso mide lo bien que seguiste tu plan, no tu P&L. Un día en rojo ejecutado a la perfección es un 5. ¿Prefieres el papel? Imprime la <a href=\"@trading-templates.html\">plantilla gratis de diario</a>."))}</p>'
            + H(T("Month 1 gate","La porte du mois 1","La puerta del mes 1")) + f'<p>{t(T("Your ticket to Month 2. Every criterion is about process.","Ton billet pour le mois 2. Chaque critère porte sur le processus.","Tu pase al mes 2. Cada criterio es de proceso."))}</p>' + _checks(t, M1_GATE)
            + _ul(t, [T("<b>Gate passed:</b> Month 2 unlocks.","<b>Porte franchie :</b> le mois 2 s’ouvre.","<b>Puerta superada:</b> se abre el mes 2."), T("<b>Not yet:</b> repeat Weeks 3 and 4, focused on your most frequent slip. That’s the right call, not a setback.","<b>Pas encore :</b> refais les semaines 3 et 4, en visant ton écart le plus fréquent. C’est la bonne décision, pas un recul.","<b>Todavía no:</b> repite las semanas 3 y 4, centrado en tu desliz más frecuente. Es la decisión correcta, no un retroceso.")])
            + f'<p class="fine">{t(T("Thirty days and a small sample of trades don’t prove profitability. Month 1 proves something else: that you can follow a plan.","Trente jours et un petit échantillon de trades ne prouvent pas la rentabilité. Le mois 1 prouve autre chose : que tu sais suivre un plan.","Treinta días y una muestra pequeña de operaciones no prueban la rentabilidad. El mes 1 prueba otra cosa: que sabes seguir un plan."))}</p>')
    return _month_page(lang, t, 1, T("90-day gameplan · Month 1","Plan de 90 jours · Mois 1","Plan de 90 días · Mes 1"),
        T("Month 1: protect first, then execute.","Mois 1 : protège d’abord, exécute ensuite.","Mes 1: primero protege, luego ejecuta."),
        T("Thirty days of short daily missions to trade your first micro futures with guardrails, one setup and one process. MES or MNQ, in sim or on your evaluation, 15 to 30 minutes a day.",
          "Trente jours de courtes missions quotidiennes pour trader tes premiers micro futures avec des garde-fous, un setup et un processus. MES ou MNQ, en simulation ou sur ton évaluation, 15 à 30 minutes par jour.",
          "Treinta días de misiones diarias cortas para operar tus primeros micro futuros con barreras, un setup y un proceso. MES o MNQ, en simulación o en tu evaluación, de 15 a 30 minutos al día."),
        body, T("Prop Firm Gameplan, Month 1: Foundation · Sweep","Plan prop firm, mois 1 : les fondations · Sweep","Plan prop firm, mes 1: los cimientos · Sweep"),
        T("Month 1 of the 90-day prop firm gameplan: 8 guardrails, the Sweep Setup on MES or MNQ, a 10-minute session routine and 30 daily missions.",
          "Mois 1 du plan prop firm de 90 jours : 8 garde-fous, le Sweep Setup sur MES ou MNQ, une routine de séance de 10 minutes et 30 missions quotidiennes.",
          "Mes 1 del plan prop firm de 90 días: 8 barreras, el Sweep Setup en MES o MNQ, una rutina de sesión de 10 minutos y 30 misiones diarias."), "signup_gameplan_m1")

def page_gp_month2(lang, t):
    H = lambda x: f"<h2>{t(x)}</h2>"
    rules = RULES_1_8[:6] + [RULE_7_M2, RULES_1_8[7]]
    seg = T("PDH shorts, PDL longs, the early, middle and late blocks, A grades, B grades, and trades taken after a loss.","Ventes au PDH, achats au PDL, blocs du début, du milieu et de la fin, notes A, notes B, et trades pris après une perte.","Ventas en el PDH, compras en el PDL, bloques del inicio, del medio y del final, notas A, notas B y operaciones tomadas tras una pérdida.")
    body = (H(T("Month 2 at a glance","Le mois 2 en bref","El mes 2 de un vistazo")) + f'<p>{t(T("Month 1 proved you can follow a plan. Month 2 shows you what your plan actually does.","Le mois 1 a prouvé que tu sais suivre un plan. Le mois 2 te montre ce que ton plan donne vraiment.","El mes 1 demostró que sabes seguir un plan. El mes 2 te muestra lo que tu plan da de verdad."))}</p>'
            + f'<h3>{t(T("What’s new","Ce qui est nouveau","Lo nuevo"))}</h3>' + _ul(t, M2_NEW) + f'<h3>{t(T("What doesn’t change","Ce qui ne change pas","Lo que no cambia"))}</h3>' + _ul(t, M2_SAME)
            + _note(t, T("Days keep counting","Les jours continuent de compter","Los días siguen contando"), T("Month 2 runs from Day 31 to Day 60. If you started Month 1 on a Monday, Day 31 is a Wednesday; the weekly recap stays on Friday.","Le mois 2 va du jour 31 au jour 60. Si tu as commencé le mois 1 un lundi, le jour 31 tombe un mercredi ; le bilan de la semaine reste le vendredi.","El mes 2 va del día 31 al día 60. Si empezaste el mes 1 un lunes, el día 31 cae en miércoles; el resumen semanal sigue siendo el viernes."))
            + H(T("Your guardrails, version 2","Tes garde-fous, version 2","Tus barreras, versión 2")) + f'<p>{t(T("The 8 rules of Month 1 stay. Two are added, aimed at the two moments that cost accounts the most: right after a loss, and right after a good run.","Les 8 règles du mois 1 restent. Deux s’ajoutent, pour les deux moments qui coûtent le plus de comptes : juste après une perte, et juste après une belle série.","Las 8 reglas del mes 1 se quedan. Se añaden dos, para los dos momentos que más cuentas cuestan: justo después de una pérdida y justo después de una buena racha."))}</p>'
            + _ol(t, rules + [T(NEW["en"] + RULE_9["en"], NEW["fr"] + RULE_9["fr"], NEW["es"] + RULE_9["es"]), T(NEW["en"] + RULE_10["en"], NEW["fr"] + RULE_10["fr"], NEW["es"] + RULE_10["es"])])
            + f'<p>{t(T("Month 2 targets: at least 25 executed trades, at least 60 setups logged (live and replay), an average process score of 4 or more, and your monthly spending budget.","Objectifs du mois 2 : au moins 25 trades exécutés, au moins 60 setups notés (en direct et en replay), une note de processus moyenne de 4 ou plus, et ton budget de dépenses du mois.","Objetivos del mes 2: al menos 25 operaciones ejecutadas, al menos 60 setups anotados (en directo y en replay), una nota de proceso media de 4 o más, y tu presupuesto de gastos del mes."))}</p>'
            + H(T("Tag every trade","Étiquette chaque trade","Etiqueta cada operación")) + f'<p>{t(T("Tags turn your journal into data: five seconds per trade. In Sweep, they go on the trade itself.","Les étiquettes transforment ton journal en données : cinq secondes par trade. Dans Sweep, elles se mettent sur le trade lui-même.","Las etiquetas convierten tu diario en datos: cinco segundos por operación. En Sweep, van en la propia operación."))}</p>' + _tbl(t, TAGS)
            + f'<h3>{t(T("What counts as a pattern","Ce qui compte comme une tendance","Qué cuenta como un patrón"))}</h3>' + _ul(t, PATTERN)
            + _note(t, T("Small samples lie","Les petits échantillons mentent","Las muestras pequeñas mienten"), T("Sixty setups is a start, not proof. Read your data as a direction to test, never as a guarantee.","Soixante setups, c’est un début, pas une preuve. Lis tes données comme une piste à tester, jamais comme une garantie.","Sesenta setups son un comienzo, no una prueba. Lee tus datos como una dirección que probar, nunca como una garantía."))
            + H(T("Your one change","Ton seul changement","Tu único cambio")) + f'<p>{t(T("After three weeks of data (Day 42), you may change one thing. Or nothing: that’s a valid answer too.","Après trois semaines de données (jour 42), tu peux changer une chose. Ou rien : c’est aussi une réponse valable.","Tras tres semanas de datos (día 42), puedes cambiar una cosa. O nada: también es una respuesta válida."))}</p>'
            + f'<h3>{t(T("The rules of refining","Les règles de l’ajustement","Las reglas del ajuste"))}</h3>' + _ol(t, REFINE_RULES)
            + f'<h3>{t(T("Examples of valid refinements","Exemples d’ajustements valables","Ejemplos de ajustes válidos"))}</h3>' + _ul(t, REFINE_EX)
            + f'<h3>{t(T("Pattern review (Day 41)","Revue des tendances (jour 41)","Revisión de patrones (día 41)"))}</h3><p>{t(T("Compare these segments by number of trades, win rate, average R and plan followed: ","Compare ces segments par nombre de trades, taux de réussite, R moyen et plan suivi : ","Compara estos segmentos por número de operaciones, tasa de acierto, R medio y plan seguido: "))}{t(seg)}</p>'
            + _weeks(t, lang, 31, M2_WEEKS)
            + H(T("Your session journal, version 2","Ton journal de séance, version 2","Tu diario de sesión, versión 2")) + f'<p>{t(T("The same journal, now with tags. Passed setups count.","Le même journal, maintenant avec des étiquettes. Les setups passés comptent.","El mismo diario, ahora con etiquetas. Los setups descartados cuentan."))}</p>' + _ul(t, M2_JOURNAL)
            + f'<p class="fine">{t(T("For passed setups, note the result the trade would have had in R. It tells you whether your filter is helping.","Pour les setups passés, note le résultat qu’aurait eu le trade en R. Ça te dit si ton filtre aide.","Para los setups descartados, anota el resultado que habría tenido la operación en R. Te dice si tu filtro ayuda."))}</p>'
            + H(T("Month 2 gate","La porte du mois 2","La puerta del mes 2")) + f'<p>{t(T("Your ticket to Month 3. Still about process, now backed by data.","Ton billet pour le mois 3. Toujours le processus, maintenant appuyé par les données.","Tu pase al mes 3. Sigue siendo el proceso, ahora respaldado por datos."))}</p>' + _checks(t, M2_GATE)
            + _ul(t, [T("<b>Gate passed, Track A:</b> Month 3 unlocks. Starting an evaluation becomes an option, as a separate decision.","<b>Porte franchie, parcours A :</b> le mois 3 s’ouvre. Commencer une évaluation devient une option, comme décision à part.","<b>Puerta superada, recorrido A:</b> se abre el mes 3. Empezar una evaluación pasa a ser una opción, como decisión aparte."),
                      T("<b>Gate passed, Track B:</b> Month 3 unlocks on your current account.","<b>Porte franchie, parcours B :</b> le mois 3 s’ouvre sur ton compte actuel.","<b>Puerta superada, recorrido B:</b> se abre el mes 3 en tu cuenta actual."),
                      T("<b>Not yet:</b> repeat Weeks 7 and 8, focused on your most frequent slip.","<b>Pas encore :</b> refais les semaines 7 et 8, en visant ton écart le plus fréquent.","<b>Todavía no:</b> repite las semanas 7 y 8, centrado en tu desliz más frecuente.")])
            + f'<p class="fine">{t(T("Sixty days of data is a better picture, not a proof of edge. What you’ve built is a process you can measure, and everything after this depends on it.","Soixante jours de données donnent une meilleure image, pas une preuve d’edge. Tu as bâti un processus mesurable, et tout ce qui suit en dépend.","Sesenta días de datos dan una imagen mejor, no una prueba de ventaja. Has construido un proceso medible, y todo lo que viene después depende de él."))}</p>')
    return _month_page(lang, t, 2, T("90-day gameplan · Month 2","Plan de 90 jours · Mois 2","Plan de 90 días · Mes 2"),
        T("Month 2: same setup, now measure it.","Mois 2 : même setup, maintenant on mesure.","Mes 2: mismo setup, ahora mídelo."),
        T("Thirty days to build a real sample, read your own data and make one change the numbers justify. Days 31 to 60, still on 1 micro.",
          "Trente jours pour bâtir un vrai échantillon, lire tes propres données et faire un seul changement que les chiffres justifient. Jours 31 à 60, toujours avec 1 micro.",
          "Treinta días para construir una muestra real, leer tus propios datos y hacer un solo cambio que las cifras justifiquen. Días 31 a 60, todavía con 1 micro."),
        body, T("Prop Firm Gameplan, Month 2: Consistency · Sweep","Plan prop firm, mois 2 : la constance · Sweep","Plan prop firm, mes 2: la constancia · Sweep"),
        T("Month 2 of the 90-day prop firm gameplan: tag every trade, find your patterns, make one data-backed change, then trade under your firm’s real limits.",
          "Mois 2 du plan prop firm de 90 jours : étiquette chaque trade, trouve tes tendances, fais un changement appuyé par tes données, puis trade sous tes vraies limites.",
          "Mes 2 del plan prop firm de 90 días: etiqueta cada operación, encuentra tus patrones, haz un cambio respaldado por datos y opera con los límites reales."), "signup_gameplan_m2")

def page_gp_month3(lang, t):
    H = lambda x: f"<h2>{t(x)}</h2>"
    rules = [RULE_1_M3] + RULES_1_8[1:6] + [RULE_7_M3, RULES_1_8[7], RULE_9, RULE_10, T(NEW["en"] + RULE_11["en"], NEW["fr"] + RULE_11["fr"], NEW["es"] + RULE_11["es"])]
    body = (H(T("Month 3 at a glance","Le mois 3 en bref","El mes 3 de un vistazo")) + f'<p>{t(T("You can follow a plan, and you can measure it. Now you run it where it counts.","Tu sais suivre un plan, et tu sais le mesurer. Maintenant, tu le mets en jeu là où ça compte.","Sabes seguir un plan y sabes medirlo. Ahora lo pones en juego donde cuenta."))}</p>'
            + f'<h3>{t(T("What’s new","Ce qui est nouveau","Lo nuevo"))}</h3>' + _ul(t, M3_NEW) + f'<h3>{t(T("What doesn’t change","Ce qui ne change pas","Lo que no cambia"))}</h3>' + _ul(t, M3_SAME)
            + f'<h3>{t(T("Choose your arena (Day 62)","Choisis ton terrain (jour 62)","Elige tu terreno (día 62)"))}</h3>' + _tbl(t, ARENA)
            + H(T("Your guardrails, version 3","Tes garde-fous, version 3","Tus barreras, versión 3")) + f'<p>{t(T("Rule 1 now follows the size ladder. One rule is added for the moment most traders give it all back: right after a win.","La règle 1 suit maintenant l’échelle de taille. Une règle s’ajoute pour le moment où la plupart des traders redonnent tout : juste après un gain.","La regla 1 sigue ahora la escalera de tamaño. Se añade una regla para el momento en que la mayoría de los traders lo devuelve todo: justo después de ganar."))}</p>' + _ol(t, rules)
            + _note(t, T("No impulse purchases","Aucun achat impulsif","Nada de compras impulsivas"), T("Failed an evaluation? A 3-day cooldown and a full review of your journal before buying another one. Every purchase stays inside your monthly budget.","Évaluation ratée ? Un délai de 3 jours et une revue complète de ton journal avant d’en acheter une autre. Chaque achat reste dans ton budget du mois.","¿Fallaste una evaluación? 3 días de espera y una revisión completa de tu diario antes de comprar otra. Cada compra se queda dentro de tu presupuesto mensual."))
            + H(T("The size ladder","L’échelle de taille","La escalera de tamaño")) + f'<p>{t(T("Your risk grows only when your execution justifies it. Up slowly, down instantly.","Ton risque grandit seulement quand ton exécution le justifie. On monte lentement, on descend tout de suite.","Tu riesgo crece solo cuando tu ejecución lo justifica. Se sube despacio, se baja al instante."))}</p>' + _tbl(t, LADDER)
            + f'<h3>{t(T("Step down immediately if","Redescends tout de suite si","Baja de inmediato si"))}</h3>' + _ul(t, STEP_DOWN)
            + f'<p class="fine">{t(T("Stepping down is not a punishment. It’s the ladder doing its job: you climb back with the same criteria.","Redescendre n’est pas une punition. C’est l’échelle qui fait son travail : tu remontes avec les mêmes critères.","Bajar no es un castigo. Es la escalera haciendo su trabajo: vuelves a subir con los mismos criterios."))}</p>'
            + H(T("Pass with a plan, not with speed","Réussir avec un plan, pas avec de la vitesse","Aprobar con un plan, no con velocidad")) + f'<p>{t(T("An evaluation rewards the trader who doesn’t break rules, not the one who goes fastest. Before your first session (Day 63), write down your firm, account type, profit target, daily loss limit, max drawdown (static or trailing), consistency rule and other rules: minimum days, time limit, news, scaling. Each firm’s current rules are on our <a href=\"@prop-firms/index.html\">prop firm pages</a>. Track A, option 2: use the evaluation you’d buy.","Une évaluation récompense le trader qui ne brise pas de règles, pas celui qui va le plus vite. Avant ta première séance (jour 63), note ta firme, ton type de compte, l’objectif de profit, la limite de perte quotidienne, le drawdown max (statique ou suiveur), la règle de consistance et les autres règles : jours minimum, limite de temps, nouvelles, paliers. Les règles actuelles de chaque firme sont sur nos <a href=\"@prop-firms/index.html\">pages des prop firms</a>. Parcours A, option 2 : prends l’évaluation que tu achèterais.","Una evaluación premia al trader que no rompe reglas, no al que va más rápido. Antes de tu primera sesión (día 63), anota tu firma, tu tipo de cuenta, el objetivo de beneficio, el límite de pérdida diaria, el drawdown máximo (estático o dinámico), la regla de consistencia y las demás reglas: días mínimos, límite de tiempo, noticias, escalado. Las reglas actuales de cada firma están en nuestras <a href=\"@prop-firms/index.html\">páginas de prop firms</a>. Recorrido A, opción 2: usa la evaluación que comprarías."))}</p>'
            + f'<h3>{t(T("Your numbers","Tes chiffres","Tus cifras"))}</h3>' + _tbl(t, EVAL_MATH)
            + _note(t, T("The math that keeps you calm","Les maths qui gardent ton calme","Las cuentas que te mantienen en calma"), T("If your target is 20R away, it takes many good sessions, not one great one. No firm deadline justifies breaking your rules. If your firm has a time limit, check it now, not when it’s close.","Si ton objectif est à 20R, il faut beaucoup de bonnes séances, pas une seule grande. Aucune échéance de firme ne justifie de briser tes règles. Si ta firme a une limite de temps, vérifie-la maintenant, pas quand elle approche.","Si tu objetivo está a 20R, hacen falta muchas buenas sesiones, no una sola gran sesión. Ningún plazo de la firma justifica romper tus reglas. Si tu firma tiene un límite de tiempo, revísalo ahora, no cuando se acerque."))
            + f'<h3>{t(T("If it doesn’t pass","Si ça ne passe pas","Si no apruebas"))}</h3><p>{t(T("Your plan stays the same. A failed evaluation tells you whether you followed your rules: check that first in your journal. Then the cooldown rule applies.","Ton plan reste le même. Une évaluation ratée te dit si tu as suivi tes règles : vérifie-le d’abord dans ton journal. Puis la règle du délai s’applique.","Tu plan sigue igual. Una evaluación fallida te dice si seguiste tus reglas: revísalo primero en tu diario. Luego se aplica la regla de espera."))}</p>'
            + H(T("Your funded playbook","Ton playbook de compte financé","Tu playbook de cuenta financiada")) + f'<p>{t(T("Funded accounts are often lost by traders who change what got them there. Write your rules now (Day 77), while you’re calm.","Les comptes financés se perdent souvent quand le trader change ce qui l’a mené là. Écris tes règles maintenant (jour 77), pendant que tu es calme.","Las cuentas financiadas se pierden a menudo cuando el trader cambia lo que lo llevó hasta ahí. Escribe tus reglas ahora (día 77), mientras estás tranquilo."))}</p>' + _ol(t, PLAYBOOK)
            + f'<p>{t(T("Then write yours: your payout rule, what you will never change once funded, what made you pass in one sentence, and your warning sign that you’re drifting. In Sweep, <a href=\"@payout-tracker.html\">My money</a> keeps evaluation costs, funded profits and real payouts apart.","Puis écris les tiens : ta règle de payout, ce que tu ne changeras jamais une fois financé, ce qui t’a fait réussir en une phrase, et ton signal d’alerte que tu dérives. Dans Sweep, <a href=\"@payout-tracker.html\">Mon argent</a> garde à part le coût des évaluations, les profits des comptes financés et les vrais payouts.","Luego escribe los tuyos: tu regla de payout, lo que nunca cambiarás una vez financiado, lo que te hizo aprobar en una frase y tu señal de alerta de que te desvías. En Sweep, <a href=\"@payout-tracker.html\">Mi dinero</a> separa el coste de las evaluaciones, los beneficios de las cuentas financiadas y los payouts reales."))}</p>'
            + _note(t, T("The two classic mistakes","Les deux erreurs classiques","Los dos errores clásicos"), T("Wanting to maximize once it’s “real”, and forgetting the small habits that made it work. Your playbook exists for those two moments.","Vouloir maximiser une fois que c’est « pour vrai », et oublier les petites habitudes qui ont fonctionné. Ton playbook existe pour ces deux moments.","Querer maximizar una vez que es «de verdad», y olvidar los pequeños hábitos que funcionaron. Tu playbook existe para esos dos momentos."))
            + _weeks(t, lang, 61, M3_WEEKS)
            + H(T("Your one-page trading plan","Ton plan de trading d’une page","Tu plan de trading de una página")) + f'<p>{t(T("On Day 84, in your words. It replaces the gameplan from Day 91 on.","Au jour 84, dans tes mots. Il remplace le plan de 90 jours à partir du jour 91.","El día 84, con tus palabras. Sustituye al plan de 90 días a partir del día 91."))}</p>' + _ul(t, PLAN_FIELDS)
            + f'<p>{t(T("The <a href=\"@trading-templates.html\">free trading plan template</a> has room for all of it, on one printable page.","Le <a href=\"@trading-templates.html\">modèle gratuit de plan de trading</a> a de la place pour tout ça, sur une page à imprimer.","La <a href=\"@trading-templates.html\">plantilla gratis de plan de trading</a> tiene espacio para todo, en una página para imprimir."))}</p>'
            + H(T("Final gate","La porte finale","La puerta final")) + f'<p>{t(T("Passing an evaluation is not a criterion. Trading your plan is.","Réussir une évaluation n’est pas un critère. Trader ton plan, oui.","Aprobar una evaluación no es un criterio. Operar tu plan, sí."))}</p>' + _checks(t, M3_GATE)
            + _ul(t, [T("<b>Gameplan complete:</b> your plan becomes your routine. Weekly recaps and the ladder keep running.","<b>Plan terminé :</b> ton plan devient ta routine. Les bilans de la semaine et l’échelle continuent.","<b>Plan completado:</b> tu plan se convierte en tu rutina. Los resúmenes semanales y la escalera siguen."),
                      T("<b>Not yet:</b> repeat Weeks 11 and 12, focused on your most frequent slip.","<b>Pas encore :</b> refais les semaines 11 et 12, en visant ton écart le plus fréquent.","<b>Todavía no:</b> repite las semanas 11 y 12, centrado en tu desliz más frecuente.")])
            + _note(t, T("Day 91","Jour 91","Día 91"), T("There’s no finish line. Same routine, same journal, same Friday recap. When your data says so, you climb. When it says otherwise, you step down and fix one thing. That’s the whole game.","Il n’y a pas de ligne d’arrivée. Même routine, même journal, même bilan du vendredi. Quand tes données le disent, tu montes. Quand elles disent le contraire, tu redescends et tu corriges une chose. C’est tout le jeu.","No hay línea de meta. Misma rutina, mismo diario, mismo resumen del viernes. Cuando tus datos lo dicen, subes. Cuando dicen lo contrario, bajas y corriges una cosa. Ese es todo el juego."))
            + f'<p class="fine">{t(T("Ninety days don’t prove a lasting edge. They prove you can run a measurable, repeatable process: the only foundation an edge can be built on.","Quatre-vingt-dix jours ne prouvent pas un edge durable. Ils prouvent que tu sais mener un processus mesurable et répétable : la seule base sur laquelle bâtir un edge.","Noventa días no prueban una ventaja duradera. Prueban que sabes llevar un proceso medible y repetible: la única base sobre la que construir una ventaja."))}</p>')
    return _month_page(lang, t, 3, T("90-day gameplan · Month 3","Plan de 90 jours · Mois 3","Plan de 90 días · Mes 3"),
        T("Month 3: real rules, earned size.","Mois 3 : vraies règles, taille méritée.","Mes 3: reglas reales, tamaño ganado."),
        T("Thirty days to trade your process under real prop firm conditions, grow your size only when your execution earns it, and leave with your own written plan. Days 61 to 90.",
          "Trente jours pour trader ton processus dans de vraies conditions de prop firm, augmenter ta taille seulement quand ton exécution le mérite, et repartir avec ton propre plan écrit. Jours 61 à 90.",
          "Treinta días para operar tu proceso en condiciones reales de prop firm, subir tu tamaño solo cuando tu ejecución lo merezca y terminar con tu propio plan escrito. Días 61 a 90."),
        body, T("Prop Firm Gameplan, Month 3: Prove It · Sweep","Plan prop firm, mois 3 : fais tes preuves · Sweep","Plan prop firm, mes 3: demuéstralo · Sweep"),
        T("Month 3 of the 90-day prop firm gameplan: an evaluation plan, a size ladder from 1 to 3 micros, a funded playbook and your own one-page trading plan.",
          "Mois 3 du plan prop firm de 90 jours : un plan d’évaluation, une échelle de taille de 1 à 3 micros, un playbook de compte financé et ton plan d’une page.",
          "Mes 3 del plan prop firm de 90 días: un plan de evaluación, una escalera de tamaño de 1 a 3 micros, un playbook de cuenta financiada y tu plan de una página."), "signup_gameplan_m3")

